# Generated by tools/packgen/banking/make_packs.py from snippets/trading/swap_key_rate.py there. Edit that source, not this file.
# title: Swap key-rate DV01 by bump and reprice
# description: The trade's unsettled interest flows (LEGS[].CASH_FLOWS, fixed at their RATE, floating not fixed yet projected off the leg's DISCOUNT_INDEX curve) repriced with each pillar of the curve moved 1 bp in turn (triangular bumps, projection and discounting together): key-rate DV01 by pillar from full revaluation, their sum against a parallel bump, and the risk engine's DV01 (TVAL-<TRADE_ID>) beside them.
# kinds: trade

from datetime import date
import pandas as pd
from drishti import quant as q

doc = view.doc
num = lambda x: float(x) if x not in (None, "") else None          # noqa: E731 - numbers may be text or blank
as_of = date.fromisoformat(view.business_date or "2026-09-30")
yrs = lambda d: (date.fromisoformat(d) - as_of).days / 365.0         # noqa: E731
legs = [leg for leg in doc.get("LEGS") or [] if leg.get("LEG_TYPE") in ("FIXED", "FLOAT")]
cids = {leg.get("DISCOUNT_INDEX") or f"CRV-{leg.get('CURRENCY') or doc['CURRENCY']}-OIS" for leg in legs}
if len(legs) < 2 or len(cids) != 1:
    raise ValueError(f"{view.id} ({doc.get('PRODUCT_TYPE')}): this snippet is for single-currency swaps (two legs on one curve)")
cid = cids.pop()
curve = q.ZeroCurve.from_points((await drishti.get_async("ir-curve", cid))["POINTS"])


def pv(crv):
    total = 0.0
    for leg in legs:
        sign = -1 if leg.get("LEG_ECONOMIC_TYPE") == "Pay" else 1
        for cf in leg.get("CASH_FLOWS") or []:
            if not cf.get("PAYMENT_DATE") or yrs(cf["PAYMENT_DATE"]) <= 0 or cf.get("FLOW_TYPE") == "Principal":
                continue
            t0, t1 = yrs(cf["START_DATE"]), yrs(cf["END_DATE"] or cf["PAYMENT_DATE"])
            rate = crv.forward(t0, t1) + (num(cf.get("FLOAT_SPREAD")) or 0.0) if leg["LEG_TYPE"] == "FLOAT" and t0 > 0 else (num(cf.get("RATE")) or 0.0)
            total += sign * (num(cf.get("NOTIONAL")) or 0.0) * rate * max(t1 - t0, 0) * crv.df(yrs(cf["PAYMENT_DATE"]))
    return total


base = pv(curve)
rows = [{"pillar (years)": round(float(t), 3), "key-rate DV01": pv(curve.key_rate_bumped(i, 1.0)) - base}
        for i, t in enumerate(curve.times)]
kr = pd.DataFrame(rows)
parallel = pv(curve.shifted(1.0)) - base
show(kr, title=f"{view.id}: key-rate DV01 on {cid} (PV {base:,.0f} {doc['CURRENCY']})")
try:
    booked = (await drishti.get_async("trade-valuation", f"TVAL-{doc['TRADE_ID']}"))["DV01"]
except Exception:                                                     # market-risk not installed
    booked = None
print(f"Sum of key rates {kr['key-rate DV01'].sum():,.0f}; parallel +1 bp {parallel:,.0f}; risk engine DV01 {booked}")
chart(kr, kind="bar", x="pillar (years)", y="key-rate DV01", title="Key-rate DV01 by pillar (+1 bp)")
